        using var fs = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read);
        var data = new byte[32];
        int count = 0;
        while (fs.Read(data, 0, data.Length) != 0 && count < 16) { count++; }
        return Convert.ToHexString(SHA256.HashData(data));
